{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Bath Sessions</title>
  <meta name="description" content="A premium sensory sound bath in {{CITY}}, {{STATE}} led by {{FACILITATOR_NAME}}. Restorative group and private offerings.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-bold-playful">
  <header class="site-header">
    <div class="wrapper">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/events.html">Upcoming</a>
        <a href="/private-sessions.html">Private</a>
        <a href="/pricing.html">Fees</a>
        <a href="/about.html">About</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <button class="nav-toggle" aria-label="Toggle menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <svg class="hero-bg" preserveAspectRatio="none" viewBox="0 0 800 300" aria-hidden="true">
        <defs>
          <linearGradient id="g1" x1="0" x2="1">
            <stop offset="0%" stop-color="#c7f3ff" />
            <stop offset="100%" stop-color="#f3e8ff" />
          </linearGradient>
        </defs>
        <rect width="800" height="300" fill="url(#g1)"></rect>
      </svg>
      <div class="wrapper hero-content">
        <h1 class="headline">Float into a curated sound journey — gentle, clinical, and luxuriously restorative</h1>
        <p class="tagline">{{TAGLINE}} — intimate group sound baths and one-to-one sessions in {{CITY}}, led by {{FACILITATOR_NAME}}.</p>
        <div class="hero-actions">
          <a class="btn primary" href="/events.html">See Next Events</a>
          <a class="btn ghost" href="/private-sessions.html">Book Private Session</a>
        </div>
        <p class="meta">Next public session: <strong id="next-event" data-next-event="{{NEXT_EVENT_DATE}}">{{NEXT_EVENT_DATE}}</strong></p>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section class="truths wrapper" id="myth_vs_truth">
      <h2>Myths, then clarity</h2>
      <div class="grid-2">
        <div class="card">
          <h3>Myth: A sound bath is mystical theatrics</h3>
          <p>Truth: It’s guided sensory modulation using precise tones to calm the nervous system. We design each session with clinical calm to create reliable relaxation responses.</p>
        </div>
        <div class="card">
          <h3>Myth: You need to surrender control</h3>
          <p>Truth: You remain fully present. Practices are accessible, adaptive, and trauma-informed. Expect gentle instruction and options to opt out anytime.</p>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section class="pillars" id="pillars">
      <div class="wrapper">
        <h2>We build sessions on three pillars</h2>
        <div class="three-grid">
          <article class="pillar">
            <h4>Precision</h4>
            <p>Curated instruments (crystal singing bowls, tuning forks, chimes) tuned to intention and breath patterns to guide nervous system regulation.</p>
          </article>
          <article class="pillar">
            <h4>Safety</h4>
            <p>Facilitator-led briefings, contraindications screening, and clear exit signals to ensure every participant feels in control.</p>
          </article>
          <article class="pillar">
            <h4>Ritual with reason</h4>
            <p>We use a predictable flow—arrival, grounding, sound immersion, gentle return—to create dependable transitions into and out of deep rest.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- CASE NOTES (TESTIMONIALS / CASE STUDIES) -->
    <section class="case-notes wrapper" id="case_notes">
      <h2>Case notes</h2>
      <p class="lede">Real feedback from participants who experienced the methodology-first approach.</p>
      <div class="notes">
        <blockquote class="note">
          <p>"I slept more deeply the night of the session than I have in months. The bowls and a single gong strike were astonishingly effective."</p>
          <cite>- Local attendee, {{CITY}}</cite>
        </blockquote>
        <blockquote class="note">
          <p>"Our team retreat included a corporate 60-minute sound offering. The facilitator adapted tones for a mixed-sensory group and the results were measurable: calmer post-session feedback."</p>
          <cite>- HR Lead</cite>
        </blockquote>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq wrapper" id="faq">
      <h2>Common questions</h2>
      <div class="faq-list">
        <div class="faq-item">
          <button class="q">What should I bring?</button>
          <div class="a">Bring a yoga mat or blanket, eye pillow, water, and an optional thin pillow for neck support. Dress in comfortable layers for temperature changes.</div>
        </div>
        <div class="faq-item">
          <button class="q">Are there any contraindications?</button>
          <div class="a">If you are pregnant, have a pacemaker, recent head injury, uncontrolled seizures, or severe hearing conditions, consult your medical provider first and inform the facilitator. Sessions are not a replacement for medical care.</div>
        </div>
        <div class="faq-item">
          <button class="q">What is the flow of a typical session?</button>
          <div class="a">Arrival & quieting (10 min), orientation & intention (5–10 min), sound immersion (30–45 min), soft reentry & journaling (10–15 min). Facilitator guides transitions throughout.</div>
        </div>
        <div class="faq-item">
          <button class="q">Which instruments do you use?</button>
          <div class="a">We may use crystal bowls, chimes, a monochord, and targeted tuning forks. Instrument selection varies by session focus.</div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta-block wrapper" id="cta">
      <div class="cta-inner">
        <h2>Reserve a nurturing pause</h2>
        <p>Is now the moment to prioritize rest? Book a seat at a scheduled group sound bath or arrange a private, one-to-one session with {{FACILITATOR_NAME}}.</p>
        <div class="cta-actions">
          <a class="btn primary" href="/book.html">Book Now</a>
          <a class="btn ghost" href="/private-sessions.html">Private Options</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrapper">
      <div class="footer-col">
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{VENUE_NAME}} — {{CITY}}, {{STATE}}</p>
      </div>
      <div class="footer-col">
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
      <div class="footer-col">
        <nav class="foot-nav">
          <a href="/about.html">Who we are</a>
          <a href="/faq.html">FAQ</a>
          <a href="/contact.html">Connect</a>
        </nav>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
