{"path":"assets/css/styles.css","content":"/* Core styles for bold_playful / clinical_calm theme */
:root{
  --bg:#fbfdff;
  --muted:#6b6f76;
  --accent:#7bd389;
  --accent-2:#8cc0ff;
  --glass:rgba(255,255,255,0.6);
  --card:#ffffff;
  --radius:12px;
  --fw-semibold:600;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;line-height:1.45;color:#0f1724;background:linear-gradient(180deg,var(--bg),#f7fbff);}
.wrapper{max-width:1100px;margin:0 auto;padding:28px}
.site-header{position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.8),rgba(255,255,255,0.65));backdrop-filter:blur(6px);border-bottom:1px solid rgba(10,10,12,0.04)}
.site-header .wrapper{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:#0b1220;text-decoration:none;font-size:1.1rem}
.main-nav{margin-left:8px;display:flex;gap:12px}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
.cta{margin-left:auto;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#06202a;padding:8px 14px;border-radius:10px;text-decoration:none;font-weight:700}
.nav-toggle{display:none;border:0;background:transparent;font-size:1.2rem}

.hero{position:relative;overflow:hidden;padding:48px 0}
.hero-bg{position:absolute;left:0;top:0;width:120%;height:140%;opacity:0.85;transform:rotate(-6deg)}
.hero-content{position:relative;padding:40px 24px;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.4));border-radius:16px;backdrop-filter:blur(6px);display:grid;gap:14px}
.headline{margin:0;font-size:clamp(1.4rem,2.4vw,2.2rem);color:#071234}
.tagline{color:var(--muted);margin:0}
.hero-actions{display:flex;gap:10px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#042229;font-weight:700}
.btn.ghost{background:transparent;border:1px solid rgba(12,14,20,0.06);color:var(--muted)}
.meta{color:var(--muted);font-size:0.95rem}

.truths{padding:36px 0}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(14,22,34,0.06)}
.card h3{margin-top:0}

.pillars{padding:36px 0}
.three-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.pillar{background:linear-gradient(180deg,#fff,#fbffff);padding:18px;border-radius:12px}
.pillar h4{margin:0 0 8px 0}

.case-notes{padding:36px 0}
.notes{display:flex;flex-direction:column;gap:12px}
.note{background:var(--card);padding:16px;border-radius:12px}
.note cite{display:block;margin-top:8px;color:var(--muted);font-size:0.9rem}

.faq{padding:36px 0}
.faq-list{display:grid;gap:10px}
.faq-item{background:var(--card);border-radius:10px;padding:10px}
.faq-item .q{width:100%;text-align:left;background:transparent;border:0;padding:12px;font-weight:700;font-size:1rem}
.faq-item .a{display:none;padding:0 12px 12px 12px;color:var(--muted)}

.cta-block{padding:40px 0}
.cta-inner{background:linear-gradient(180deg,rgba(123,211,137,0.08),rgba(140,192,255,0.06));padding:22px;border-radius:14px}
.cta-actions{display:flex;gap:10px;margin-top:12px}

.site-footer{border-top:1px solid rgba(10,10,12,0.04);padding:22px 0;margin-top:24px}
.site-footer .wrapper{display:flex;gap:24px;align-items:center}
.footer-col{flex:1}
.foot-nav a{display:block;color:var(--muted);text-decoration:none}

/* pattern background in sections */
section{background-image:url('/assets/img/pattern.svg');background-repeat:no-repeat;background-position:right top;background-size:380px}

/* Responsive */
@media (max-width:900px){
  .grid-2{grid-template-columns:1fr}
  .three-grid{grid-template-columns:1fr}
  .main-nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
  .hero-bg{display:none}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var toggle=document.querySelector('.nav-toggle');
  var nav=document.querySelector('.main-nav');
  toggle&&toggle.addEventListener('click',function(){
    if(nav.style.display==='flex'){nav.style.display='none'}else{nav.style.display='flex';nav.style.flexDirection='column'}
  });

  // FAQ accordion
  var qs=document.querySelectorAll('.faq-item .q');
  qs.forEach(function(btn){
    btn.addEventListener('click',function(){
      var a=this.nextElementSibling;
      var open= a.style.display==='block';
      // close all
      document.querySelectorAll('.faq-item .a').forEach(function(el){el.style.display='none'});
      if(!open){a.style.display='block'}
    });
  });

  // Format next event date if present
  function formatISODate(iso){
    try{
      var d=new Date(iso);
      if(isNaN(d)) return iso;
      return d.toLocaleString(undefined,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'numeric'});
    }catch(e){return iso}
  }
  var next=document.getElementById('next-event');
  if(next){
    var raw=next.getAttribute('data-next-event');
    if(raw && raw.indexOf('{')===-1){ next.textContent=formatISODate(raw); }
  }

  // Smooth scroll for internal anchors
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var tgt=document.querySelector(this.getAttribute('href'));
      if(tgt){e.preventDefault();tgt.scrollIntoView({behavior:'smooth',block:'start'});} 
    });
  });
})();"} 
